package org.healthrenewal.rawafid;

import java.util.ArrayList;
import java.util.List;

/** 8 periods x 5 openers x 5 care ideas x 5 closers = 1000 distinct daily-care messages. */
public final class MessageBank {
    private MessageBank(){}
    private static final String[][] OPENERS = {
        {"صباحك يبدأ من عندكِ،", "قبل أن يدخل اليوم في سرعته،", "صباح جديد أمامكِ،", "أول لحظات اليوم لكِ،", "ابدئي هذا الصباح بلطف،"},
        {"مر جزء من الصباح،", "الآن بعد أن بدأ يومكِ،", "وسط حركة الصباح،", "قبل أن تتسارع المهام،", "لحظة صغيرة في صباحكِ،"},
        {"قبل الظهر بقليل،", "وأنتِ تقتربين من منتصف اليوم،", "هذه محطة قصيرة قبل الظهر،", "قبل أن يكتمل نصف اليوم،", "دعينا نطمئن عليكِ الآن،"},
        {"وصلنا إلى منتصف اليوم،", "نصف اليوم مضى،", "في هذه الاستراحة من اليوم،", "الآن وقت مراجعة لطيفة،", "منتصف اليوم فرصة لإعادة الضبط،"},
        {"العصر يكشف طاقتكِ الحقيقية،", "بعد يوم بدأ يطول،", "هذه لحظة عصر هادئة،", "قبل الجزء الأخير من النهار،", "دعينا نخفف إيقاع العصر قليلًا،"},
        {"بدأ المساء يقترب،", "مع هدوء المساء الأول،", "الآن يمكن لليوم أن يبطئ قليلًا،", "بين النهار والمساء،", "هذه لحظة انتقال تخصكِ،"},
        {"الآن أصبح اليوم خلفكِ أكثر مما هو أمامكِ،", "في هدوء المساء،", "قبل أن يغلق اليوم صفحته،", "المساء مساحة ألين،", "بعد ما حمله اليوم،"},
        {"قبل النوم،", "حان وقت ترك اليوم يهدأ،", "قبل أن تضعي رأسكِ على الوسادة،", "آخر لحظات اليوم تستحق الهدوء،", "غدًا موجود، فلا تحمليه الآن،"}
    };
    private static final String[][] CORES = {
        {"اسألي نفسكِ بصدق: ما الشعور الأقرب لكِ الآن؟", "خذي بضع رشفات ماء واجعلي البداية أهدأ.", "اختاري شيئًا واحدًا تريدين أن يكون لطيفًا اليوم.", "افتحي نافذة أو ضوءًا ودعي المكان يساعدكِ على الاستيقاظ.", "لا تبدئي يومكِ بمحاسبة نفسكِ على الأمس."},
        {"هل يحتاج جسمكِ ماءً أو إفطارًا أو مجرد دقيقة هدوء؟", "خففي كتفيكِ وخذي نفسًا أبطأ من المعتاد.", "رتبي المهمة التالية فقط، وليس اليوم كله.", "امنحي عينيكِ دقيقة بعيدًا عن الشاشة.", "اختاري شيئًا صغيرًا يجعلكِ مرتاحة في مظهركِ أو مكانكِ."},
        {"توقفي لحظة واسألي: هل أنا جائعة أم متعبة أم متوترة؟", "حركي جسمكِ لدقائق بالطريقة التي تناسبكِ.", "أعيدي ترتيب أولويات الساعات القادمة بلا جلد للذات.", "اكتبي الفكرة التي تستهلك أكبر مساحة في رأسكِ.", "افعلي شيئًا بسيطًا لأنكِ تحبينه لا لأن أحدًا طلبه."},
        {"اجعلي الغداء أو الاستراحة لحظة حقيقية لا مهمة إضافية.", "ما الذي يحتاج أن يصبح أخف في النصف الثاني من اليوم؟", "إذا كان الصباح صعبًا فلا تحكمي على بقية اليوم من خلاله.", "اشربي ماءً واجلسي بطريقة أريح لجسدكِ.", "اختاري عشر دقائق لا يملكها جدول أحد غيركِ."},
        {"هل تحتاجين دفعة صغيرة أم مساحة هادئة؟", "خذي استراحة قصيرة قبل أن يقرر التعب عنكِ.", "إذا انخفض تركيزكِ، اختاري مهمة واحدة واضحة فقط.", "غيري المكان أو الإضاءة لدقائق إن استطعتِ.", "اسألي نفسكِ إن كنتِ تضغطين عليها أكثر مما يلزم."},
        {"بدلي إيقاعكِ من الإنجاز إلى الاستعادة تدريجيًا.", "ارتدي شيئًا مريحًا واجعليها إشارة أن يوم العمل يخف.", "اتركي للهاتف مسافة قصيرة وامنحي رأسكِ هدوءًا.", "اختاري مشروبًا تحبينه واجلسي معه بلا استعجال.", "اسألي نفسكِ: ما الشيء الذي لا أريد حمله إلى الليل؟"},
        {"لا تحاسبي نفسكِ فقط على ما لم تنجزيه.", "تذكري شيئًا صغيرًا سار أفضل مما توقعتِ.", "خففي الإضاءة والضجيج إن كان جسمكِ يطلب الهدوء.", "اكتبي شيئًا واحدًا تريدين تركه خارج الغد.", "هل كنتِ لطيفة مع نفسكِ اليوم؟"},
        {"اتركي ما لم يكتمل لنسخة الغد منكِ.", "خففي الشاشة واجعلي الغرفة أهدأ إن استطعتِ.", "خذي نفسًا بطيئًا وأرخِي الفك والكتفين.", "لا تحولي السرير إلى اجتماع مع كل أخطاء اليوم.", "اختاري فكرة واحدة مطمئنة تغلقين بها اليوم."}
    };
    private static final String[][] CLOSERS = {
        {"لا تحتاجين للفوز باليوم في أول خمس دقائق.", "بدايتكِ الهادئة لا تعني أنكِ متأخرة.", "أنتِ جزء من جدول اليوم، لا هامشه.", "اجعلي أول قرار اليوم ألطف عليكِ.", "هذه اللحظة لكِ قبل أن تصبح للآخرين."},
        {"القليل من العناية الآن قد يغير بقية الصباح.", "لا تنتظري التعب حتى يسمح لكِ بالراحة.", "وجودكِ أهم من قائمة مهامكِ.", "يمكنكِ تعديل الإيقاع دون الشعور بالذنب.", "لا تجعلي السرعة تمنعكِ من ملاحظة نفسكِ."},
        {"ملاحظة احتياجكِ ليست أنانية.", "الوضوح يبدأ أحيانًا من دقيقة صمت.", "ليس كل شيء عاجلًا كما يبدو.", "جسدكِ يستحق أن يدخل حسابات اليوم.", "اختاري ما يساعدكِ لا ما يرهقكِ أكثر."},
        {"النصف الثاني لا يجب أن يكرر النصف الأول.", "الراحة جزء من اليوم وليست خروجًا منه.", "لا تحتاجين مبررًا للعناية بنفسكِ.", "لحظة صغيرة لكِ ليست وقتًا ضائعًا.", "يمكن ليوم عادي أن يكون يومًا جيدًا."},
        {"أنتِ من تختارين إيقاع هذه اللحظة.", "الطاقة المنخفضة معلومة وليست حكمًا عليكِ.", "خففي المهمة بدل أن تزيدي اللوم.", "أحيانًا أفضل خطوة هي أن نتوقف قليلًا.", "لا تطلبي من نفسكِ طاقة غير موجودة."},
        {"المساء لا يحتاج أن يحمل سرعة الصباح.", "اتركي مساحة لشيء جميل بلا هدف.", "الهدوء أيضًا إنجاز للجهاز العصبي.", "اجعلي البيت أو الغرفة مكانًا يستقبلكِ لا يطالبكِ.", "هذا وقت العودة إليكِ قليلًا."},
        {"يوم صعب لا يختصر حياتكِ.", "اعترفي بما فعلتِ قبل التفكير بما بقي.", "ليس عليكِ إصلاح كل شيء الليلة.", "يكفي أن تغلقي اليوم بقدر أقل من القسوة على نفسكِ.", "بعض الأيام يكفي أننا عبرناها."},
        {"النوم ليس تأجيلًا للحياة بل رعاية لها.", "لا تحتاجين حل الغد قبل أن تنامي.", "جسدكِ يستحق نهاية أكثر هدوءًا.", "يكفي لليوم ما حدث.", "دعي الليل يكون مساحة استعادة لا محاكمة."}
    };
    public static List<String> forPeriod(String period){ int idx=switch(period){case "morning_start"->0;case "morning"->1;case "late_morning"->2;case "midday"->3;case "afternoon"->4;case "early_evening"->5;case "evening"->6;default->7;}; List<String> out=new ArrayList<>(125); for(String a:OPENERS[idx])for(String b:CORES[idx])for(String c:CLOSERS[idx])out.add(a+" "+b+" "+c); return out; }
    public static int totalCount(){return 1000;}
}
